/**
 * Pushes newly created Accounts to the ERP system, one HTTP callout per
 * Account, so the ERP team can trace every account individually.
 *
 * Callouts are not allowed synchronously from a trigger (DML + callout in
 * the same transaction throws a CalloutException), so the work is handed
 * off to one or more Queueable jobs.
 *
 * Two platform limits shape the design:
 *  - At most 50 jobs can be enqueued with System.enqueueJob() in a single
 *    transaction.
 *  - Queueable chaining has a maximum stack/chain depth, which is reached
 *    well before 200 hops (confirmed by test failure "Maximum stack depth
 *    has been reached" when chaining one job per account). So chaining one
 *    job per account for a 200-record batch is not viable.
 *  - A single Queueable execution may perform up to 100 callouts.
 *
 * To satisfy "one HTTP request per account" while respecting all of the
 * above, new accounts are split into slices of at most 50 accounts. Each
 * slice gets exactly one Queueable job, enqueued directly from the trigger
 * (no chaining needed, since 200 / 50 = 4 jobs, comfortably under the
 * 50-enqueueJob-per-transaction limit). Inside each job, every account in
 * the slice is sent in its own, separate HTTP callout (one array of exactly
 * one customer per request) — so the ERP team still sees one traceable
 * request per account; a job of 50 accounts only ever uses 50 of the 100
 * callouts available to it.
 */
public with sharing class ErpCustomerSync {

    private static final String ENDPOINT = 'callout:ERP/api/customers';

    // Max accounts handled by a single Queueable job. Chosen so that even a
    // marketplace batch of 200 accounts needs only 4 jobs (200/50), well
    // under the 50-jobs-per-transaction limit, and each job performs at most
    // 50 callouts, well under the 100-callouts-per-transaction limit.
    private static final Integer MAX_ACCOUNTS_PER_JOB = 50;

    /**
     * Entry point called from the trigger. Captures the minimal data needed
     * (Id, Name, BillingCountry) for each new account, splits them into
     * slices, and enqueues one job per slice.
     */
    public static void enqueueSync(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<CustomerPayload> payloads = new List<CustomerPayload>();
        for (Account acc : newAccounts) {
            payloads.add(new CustomerPayload(acc.Id, acc.Name, acc.BillingCountry));
        }

        Integer total = payloads.size();
        for (Integer start = 0; start < total; start += MAX_ACCOUNTS_PER_JOB) {
            Integer sliceEnd = Math.min(start + MAX_ACCOUNTS_PER_JOB, total);
            List<CustomerPayload> slice = new List<CustomerPayload>();
            for (Integer i = start; i < sliceEnd; i++) {
                slice.add(payloads[i]);
            }
            System.enqueueJob(new SyncJob(slice));
        }
    }

    /**
     * Queueable that sends one callout per account in its assigned slice.
     * Each callout body is a JSON array containing exactly one customer,
     * so the ERP team can trace every account individually.
     */
    public class SyncJob implements Queueable, Database.AllowsCallouts {

        private final List<CustomerPayload> payloads;

        public SyncJob(List<CustomerPayload> payloads) {
            this.payloads = payloads;
        }

        public void execute(QueueableContext context) {
            for (CustomerPayload payload : payloads) {
                sendOne(payload);
            }
        }

        private void sendOne(CustomerPayload payload) {
            List<CustomerPayload> single = new List<CustomerPayload>{ payload };
            String body = JSON.serialize(single);

            HttpRequest req = new HttpRequest();
            req.setEndpoint(ENDPOINT);
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(body);

            Http http = new Http();
            HttpResponse res = http.send(req);

            // Error handling and retries are explicitly out of scope for this
            // ticket. We only guard against an unexpected status to aid
            // debugging.
            if (res.getStatusCode() != 202) {
                System.debug(
                    LoggingLevel.WARN,
                    'ERP sync for Account ' + payload.salesforceId +
                    ' returned unexpected status ' + res.getStatusCode() +
                    ': ' + res.getBody()
                );
            }
        }
    }

    /**
     * Wire format expected by the ERP API.
     */
    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(Id accountId, String accountName, String billingCountry) {
            this.salesforceId = accountId;
            this.name = accountName;
            this.country = billingCountry; // null when blank, as required
        }
    }
}
