/**
 * Trigger Action: prevents two Contacts on the same Account from sharing an email address
 * (compared case-insensitively). Contacts without an AccountId or without an Email are
 * not checked. Enforced on before insert and before update.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String ERROR_MESSAGE =
            'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        process(newContacts, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        Map<Id, Contact> oldContactsById = new Map<Id, Contact>((List<Contact>) triggerOld);
        process(newContacts, oldContactsById);
    }

    private void process(List<Contact> newContacts, Map<Id, Contact> oldContactsById) {
        // Determine which contacts are relevant for the duplicate check at all
        // (have both an AccountId and an Email), and - for updates - only those
        // whose Email or AccountId actually changed.
        Set<Id> accountIds = new Set<Id>();
        List<Contact> contactsToCheck = new List<Contact>();

        for (Contact newCon : newContacts) {
            if (newCon.AccountId == null || String.isBlank(newCon.Email)) {
                continue;
            }

            if (oldContactsById != null) {
                Contact oldCon = oldContactsById.get(newCon.Id);
                Boolean emailChanged = newCon.Email != oldCon.Email;
                Boolean accountChanged = newCon.AccountId != oldCon.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue;
                }
            }

            contactsToCheck.add(newCon);
            accountIds.add(newCon.AccountId);
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Single bulk-safe query: load all existing contacts (with email) on the
        // relevant accounts, excluding the records currently being saved (they are
        // in triggerNew already and would otherwise double count / self-conflict).
        Set<Id> currentIds = new Set<Id>();
        for (Contact c : contactsToCheck) {
            if (c.Id != null) {
                currentIds.add(c.Id);
            }
        }

        Map<String, Set<String>> accountIdToExistingEmails = new Map<String, Set<String>>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email != null AND Id NOT IN :currentIds
        ]) {
            String key = existing.AccountId;
            String emailLower = existing.Email.toLowerCase();
            Set<String> emails = accountIdToExistingEmails.get(key);
            if (emails == null) {
                emails = new Set<String>();
                accountIdToExistingEmails.put(key, emails);
            }
            emails.add(emailLower);
        }

        // Track account/email combinations claimed within this same save so that,
        // among several new/updated contacts sharing an account and email, only the
        // first in the list is accepted.
        Set<String> claimedInThisSave = new Set<String>();

        for (Contact con : contactsToCheck) {
            String emailLower = con.Email.toLowerCase();
            String comboKey = con.AccountId + '|' + emailLower;

            Set<String> existingEmails = accountIdToExistingEmails.get(con.AccountId);
            Boolean conflictsWithExisting = existingEmails != null && existingEmails.contains(emailLower);
            Boolean conflictsWithThisSave = claimedInThisSave.contains(comboKey);

            if (conflictsWithExisting || conflictsWithThisSave) {
                con.addError(ERROR_MESSAGE);
            } else {
                claimedInThisSave.add(comboKey);
            }
        }
    }
}
