/**
 * Singleton holder for query results shared across Contact trigger actions
 * within a single trigger execution. This avoids multiple before-insert
 * actions each issuing their own Account query for the same set of records.
 *
 * The inner `Service` class is itself registered as a Trigger Action
 * (Order__c 1, before insert) so that `accountsById` is (re)loaded first,
 * before any other action that depends on it runs. The map is reloaded on
 * every trigger execution because later DML within the same transaction can
 * involve different Accounts.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById;

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger Action that loads the parent Accounts for the Contacts
     * currently being processed. Registered with Order__c 1 so it runs
     * before any action that relies on TA_Contact_Queries.getInstance().accountsById.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject so : triggerNew) {
                Contact c = (Contact) so;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            Map<Id, Account> freshAccountsById = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                freshAccountsById = new Map<Id, Account>(
                    [
                        SELECT
                            Id,
                            BillingStreet,
                            BillingCity,
                            BillingPostalCode,
                            BillingCountry,
                            AccountSource
                        FROM Account
                        WHERE Id IN :accountIds
                    ]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = freshAccountsById;
        }
    }
}
