 * address into the Contact's mailing address fields.
 *
 * Relies on TA_Contact_Queries.getInstance().accountsById having already
 * been populated by TA_Contact_Queries.Service (Order__c 1) earlier in the
 * same before insert context, so this action performs no Account query.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;

            if (c.AccountId == null) {
                continue;
            }

            Boolean mailingAddressBlank =
                String.isBlank(c.MailingStreet) &&
                String.isBlank(c.MailingCity) &&
                String.isBlank(c.MailingPostalCode) &&
                String.isBlank(c.MailingCountry);

            if (!mailingAddressBlank) {
                continue;
            }

            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }

            c.MailingStreet = acc.BillingStreet;
            c.MailingCity = acc.BillingCity;
            c.MailingPostalCode = acc.BillingPostalCode;
            c.MailingCountry = acc.BillingCountry;
        }
    }
}
