/**
 * Before-insert Trigger Action: when a new Contact has an Account and a
 * blank LeadSource, defaults the Contact's LeadSource to the Account's
 * AccountSource.
 *
 * Relies on TA_Contact_Queries.getInstance().accountsById having already
 * been populated by TA_Contact_Queries.Service (Order__c 1) earlier in the
 * same before insert context, so this action performs no Account query.
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;

            if (c.AccountId == null) {
                continue;
            }

            if (!String.isBlank(c.LeadSource)) {
                continue;
            }

            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }

            c.LeadSource = acc.AccountSource;
        }
    }
}
